"""Generate the fixed-instance billiards pick-and-place trajectory."""
import os
os.environ['OPENBLAS_NUM_THREADS'] = '1'
import numpy as np
from scipy.spatial.transform import Rotation, Slerp
import vlb_tool


def main():
    s = vlb_tool.Session('/app/instance.json')
    down = np.array([0., 1., 0., 0.])

    def step(action):
        result = s.step(action)
        if result['done']:
            s.save_trajectory()
        return result['done']

    def move(position, fingers=.04, speed=.006, hold=8):
        start = np.array(s.env.get_ee_pos()).copy()
        start_quat = np.array(s.env.get_ee_quat()).copy()
        target = np.array(position)
        n = max(10, int(np.ceil(np.linalg.norm(target - start) / speed)))
        rotations = Rotation.from_quat(np.array([start_quat, down])[:, [1, 2, 3, 0]])
        interpolate = Slerp([0, 1], rotations)
        for t in np.linspace(0, 1, n + 1)[1:]:
            quat = interpolate([t]).as_quat()[0][[3, 0, 1, 2]]
            ik = s.ik(start * (1 - t) + target * t, quat)
            if not ik['success']:
                raise RuntimeError('Inverse kinematics failed')
            if step(np.r_[ik['joint_positions'], fingers, fingers]):
                return True
            # Persist the first available trajectory immediately.
            if len(s.actions) == 1:
                s.save_trajectory()
        for _ in range(hold):
            if step(s.targets):
                return True
        s.save_trajectory()
        return False

    ball = np.array(s.state()['entities']['snooker_black']['position'])
    if move(ball + [0, 0, .17]):
        return
    if move(ball + [0, 0, .012], speed=.003):
        return
    for _ in range(15):
        if step(np.r_[s.targets[:7], [0, 0]]):
            return
    if move(ball + [0, 0, .24], fingers=0, speed=.004):
        return
    pocket = np.array(s.state()['entities']['billiards_table']['get_place_point'][0])
    if move([pocket[0], pocket[1], .85], fingers=0, speed=.004):
        return
    if move([pocket[0], pocket[1], .73], fingers=0, speed=.003):
        return
    for _ in range(30):
        if step(np.r_[s.targets[:7], [.04, .04]]):
            print(s.status())
            s.close()
            return
    s.save_trajectory()
    raise RuntimeError('The ball did not enter the pocket')


if __name__ == '__main__':
    main()
